const queries = [
  { query: 'مسلسل تركي مدبلج بالعربية الحلقة 1',     origin: 'turkish',  language: 'ar_dubbed' },
  { query: 'مسلسل هندي مدبلج بالعربية الحلقة 1',     origin: 'indian',   language: 'ar_dubbed' },
  { query: 'مسلسل كوري مدبلج بالعربية الحلقة 1',     origin: 'korean',   language: 'ar_dubbed' },
  { query: 'مسلسل صيني مدبلج بالعربية الحلقة 1',     origin: 'chinese',  language: 'ar_dubbed' },
  { query: 'مسلسل مغربي بالدارجة الحلقة الأولى',     origin: 'moroccan', language: 'darija'    },
  { query: 'مسلسل تركي رومانسي مدبلج حلقة 1 2024',   origin: 'turkish',  language: 'ar_dubbed' },
  { query: 'مسلسل هندي دراما مدبلج عربي الحلقة 1',   origin: 'indian',   language: 'ar_dubbed' },
  { query: 'مسلسل كوري رومانسي مدبلج عربي حلقة 1',  origin: 'korean',   language: 'ar_dubbed' }
];
return queries.map(q => ({ json: q }));

const results = $input.first().json.results || [];
const query = $('Generate Queries').item.json;

function extractSeriesTitle(title) {
  return (title || '')
    .replace(/\s*(الحلقة|حلقة|ح\.?|ep\.?|episode)\s*\d+.*/gi, '')
    .replace(/\s*(الموسم|سيزون|season|الجزء|جزء|part)\s*\d+.*/gi, '')
    .replace(/\s*\d+\s*$/, '')
    .replace(/\s*(hd|4k|مدبلج|مترجم|كامل|dubbed|sub)\s*/gi, '')
    .replace(/\s*[|\-–—]\s*.+$/, '')
    .replace(/\s{2,}/g, ' ')
    .trim()
    .slice(0, 150);
}

function extractEpisodeNumber(title) {
  const m = (title || '').match(/(?:الحلقة|حلقة|ح|ep\.?|episode)\s*(\d+)/i);
  return m ? parseInt(m[1]) : null;
}

function extractSeasonNumber(title) {
  const m = (title || '').match(/(?:الموسم|سيزون|season|الجزء|جزء|part)\s*(\d+)/i);
  return m ? parseInt(m[1]) : 1;
}

const series = results
  .filter(r => r.embeddable !== false)
  .map(r => {
    const raw = r.title || '';
    const seriesTitle = extractSeriesTitle(raw);
    return {
      ytId:         r.ytId,
      raw_title:    raw,
      series_title: seriesTitle,
      origin:       (r.origin && r.origin !== 'other') ? r.origin : (query.origin || 'other'),
      language:     r.language || query.language || 'ar_dubbed',
      category:     r.category || 'drama',
      poster_url:   r.poster_url || null,
      year:         r.year || null,
      season:       extractSeasonNumber(raw),
      episode:      extractEpisodeNumber(raw),
      duration_sec: r.duration_sec || null,
      query:        query.query
    };
  })
  .filter(r => r.series_title.length >= 2);

console.log(`[Series] ${query.query} → ${series.length} usable results`);
return [{ json: { series, query: query.query } }];

const seriesList = $input.first().json.series || [];
const API_URL = 'https://mawso3a-stream.vercel.app/api/import';
const SECRET = process.env.N8N_SECRET;

let imported = 0, skipped = 0, errors = 0;
for (const s of seriesList) {
  try {
    const r = await fetch(`${API_URL}?action=smart-import-episode`, {
      method: 'POST',
      headers: { 'Authorization': `Bearer ${SECRET}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({
        ytId:         s.ytId,
        raw_title:    s.raw_title,
        series_title: s.series_title,
        season:       s.season || 1,
        episode:      s.episode || null,
        duration_sec: s.duration_sec || null,
        poster_url:   s.poster_url || null,
        source: 'youtube'
      })
    });
    const data = await r.json().catch(() => ({ ok: false }));
    data.ok ? imported++ : skipped++;
  } catch(e) {
    console.error('Error:', s.series_title || s.ytId, e.message);
    errors++;
  }
}

console.log(`[Series] DONE: ${imported} imported, ${skipped} skipped, ${errors} errors`);
return [{ json: { imported, skipped, errors, run_at: new Date().toISOString() } }];
